// Allocate once. The resident kernel keeps this slice and counter.
data := []float64{4, 9, 16, 36, 49, 64}
runs := 0
fmt.Printf("Allocated %d values at %p\n", len(data), &data[0])

// Repeating this cell keeps data and runs from the resident process.
// Each index has one writer, and Wait establishes completion before reading.
runs++
output := make([]float64, len(data))
jobs := make(chan int)
var workers sync.WaitGroup
for worker := 0; worker < 3; worker++ {
    workers.Add(1)
    go func() {
        defer workers.Done()
        for index := range jobs {
            output[index] = math.Sqrt(data[index])
        }
    }()
}
for index := range data { jobs <- index }
close(jobs)
workers.Wait()
fmt.Printf("Run %d · same data at %p\n", runs, &data[0])
fmt.Printf("Square roots in original order: %v\n", output)

// Mutation remains in RAM; rerun cell 2 to use it without reallocating data.
data[0] = 25
fmt.Printf("Updated first value to %.0f at %p. Rerun cell 2.\n", data[0], &data[0])
